package com.fpt.swp391.nutribot.entity;
import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal;
@Entity @Table(name="content_recipe_details") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class ContentRecipeDetail { @Id @Column(name="content_id") private Integer contentId; @OneToOne(fetch=FetchType.LAZY) @MapsId @JoinColumn(name="content_id") private Content content; @Column(name="prep_minutes") private Integer prepMinutes; @Column(name="cook_minutes") private Integer cookMinutes; private Integer servings; private BigDecimal calories; @Column(name="protein_g") private BigDecimal proteinG; @Column(name="carbs_g") private BigDecimal carbsG; @Column(name="fat_g") private BigDecimal fatG; @Column(name="fiber_g") private BigDecimal fiberG; @Column(name="sodium_mg") private BigDecimal sodiumMg; }
